# ---------------------------------------------------------------------------
# Unary operations
# ---------------------------------------------------------------------------

@dace.program
def frontend_negate_program(
    A: dace.float64[24, 20],
    C: dace.float64[24, 20],
):
    for i, j in dace.map[0:24, 0:20]:
        C[i, j] = -A[i, j]


@dace.program
def frontend_abs_program(
    A: dace.float64[24, 20],
    C: dace.float64[24, 20],
):
    for i, j in dace.map[0:24, 0:20]:
        C[i, j] = abs(A[i, j])


@dace.program
def frontend_cos_program(
    A: dace.float64[24, 20],
    C: dace.float64[24, 20],
):
    for i, j in dace.map[0:24, 0:20]:
        with dace.tasklet:
            a << A[i, j]
            c >> C[i, j]
            c = math.cos(a)


# ---------------------------------------------------------------------------
# Binary operations with constants
# ---------------------------------------------------------------------------

@dace.program
def frontend_a_minus_const_program(
    A: dace.float64[24, 20],
    C: dace.float64[24, 20],
):
    for i, j in dace.map[0:24, 0:20]:
        C[i, j] = A[i, j] - 5


@dace.program
def frontend_const_minus_a_program(
    A: dace.float64[24, 20],
    C: dace.float64[24, 20],
):
    for i, j in dace.map[0:24, 0:20]:
        C[i, j] = 3 - A[i, j]


@dace.program
def frontend_a_times_const_program(
    A: dace.float64[24, 20],
    C: dace.float64[24, 20],
):
    for i, j in dace.map[0:24, 0:20]:
        C[i, j] = A[i, j] * 3


# ---------------------------------------------------------------------------
# Constant-constant (frontend constant-folds 2*3 → 6)
# ---------------------------------------------------------------------------

@dace.program
def frontend_const_const_program(
    C: dace.float64[24, 20],
):
    for i, j in dace.map[0:24, 0:20]:
        C[i, j] = 2 * 3


